// Aşk mesajı ekranı: ESP32 saati NTP ile alır; OLED'de atan kalp,
// tatlı mesajlar ve "kaç gündür birlikteyiz" sayacı sırayla gösterilir.
#include <WiFi.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <time.h>

const char* AG_ADI = "EvimWiFi";    // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";   // kendi Wi-Fi parolan
const long SAAT_DILIMI = 3 * 3600;  // Türkiye UTC+3

// Birlikte olduğunuz ilk gün (yıl, ay, gün):
const int BASLANGIC_YIL = 2024;
const int BASLANGIC_AY = 2;
const int BASLANGIC_GUN = 14;

// OLED yazı tipinde Türkçe harf yok; mesajları ASCII yaz.
const char* MESAJLAR[] = {"Seni seviyorum", "Iyi ki varsin", "Kalbim senin"};
const int MESAJ_SAYISI = 3;

Adafruit_SSD1306 ekran(128, 64, &Wire, -1);
int ekranNo = 0;
unsigned long sonDegisim = 0;
unsigned long sonAtis = 0;
int kalpBoyut = 0;

void kalpCiz(int cx, int cy, int boyut) {
  int r = boyut;
  ekran.fillCircle(cx - r / 2, cy, r / 2 + 1, SSD1306_WHITE);
  ekran.fillCircle(cx + r / 2, cy, r / 2 + 1, SSD1306_WHITE);
  // Alt uç: daralan yatay çizgilerle dolu üçgen.
  for (int i = 0; i <= r; i++) {
    int yari = r - i;
    ekran.drawFastHLine(cx - yari, cy + i, yari * 2 + 1, SSD1306_WHITE);
  }
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);
  if (!ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED bulunamadi (0x3C).");
    while (true) delay(1000);
  }
  ekran.setTextColor(SSD1306_WHITE);
  ekran.clearDisplay();
  ekran.setCursor(0, 0);
  ekran.println("Wi-Fi...");
  ekran.display();

  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  unsigned long bas = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - bas < 15000) {
    delay(300);
    Serial.print(".");
  }
  Serial.println();
  configTime(SAAT_DILIMI, 0, "pool.ntp.org");
  Serial.println(WiFi.status() == WL_CONNECTED ? "Baglandi." : "Wi-Fi yok.");
}

long gunSayisi() {
  time_t simdi;
  time(&simdi);
  if (simdi < 100000) return -1;  // saat daha gelmedi
  struct tm bas = {};
  bas.tm_year = BASLANGIC_YIL - 1900;
  bas.tm_mon = BASLANGIC_AY - 1;
  bas.tm_mday = BASLANGIC_GUN;
  time_t t0 = mktime(&bas);
  return (simdi - t0) / 86400L;
}

void loop() {
  // Kalbin atışı: boyut birkaç yüz ms'de bir değişir.
  if (millis() - sonAtis > 120) {
    sonAtis = millis();
    kalpBoyut = 12 + 3 * (sin(millis() / 300.0) + 1);
  }
  if (millis() - sonDegisim > 3500) {
    sonDegisim = millis();
    ekranNo = (ekranNo + 1) % (MESAJ_SAYISI + 1);
    if (ekranNo == MESAJ_SAYISI) {
      long g = gunSayisi();
      if (g >= 0) { Serial.print(g); Serial.println(" gun birlikte"); }
    }
  }

  ekran.clearDisplay();
  kalpCiz(64, 20, kalpBoyut);

  ekran.setTextSize(1);
  if (ekranNo < MESAJ_SAYISI) {
    int gen = strlen(MESAJLAR[ekranNo]) * 6;
    ekran.setCursor((128 - gen) / 2, 52);
    ekran.print(MESAJLAR[ekranNo]);
  } else {
    long g = gunSayisi();
    ekran.setCursor(10, 48);
    if (g < 0) {
      ekran.print("Saat bekleniyor");
    } else {
      ekran.print(g);
      ekran.print(" gun birlikte");
    }
  }
  ekran.display();
  delay(30);
}
